// Transpose turns an m x n matrix into n x m (rows become columns).
func Transpose[T any](m [][]T) [][]T {
	if len(m) == 0 {
		return nil
	}
	rows, cols := len(m), len(m[0])
	out := make([][]T, cols)
	for c := 0; c < cols; c++ {
		out[c] = make([]T, rows)
		for r := 0; r < rows; r++ {
			out[c][r] = m[r][c]
		}
	}
	return out
}

