// Slugify turns any text into a URL-friendly slug.
fn slugify(text: &str) -> String {
	let s: String = text
		.to_lowercase()
		.chars()
		.map(|c| if c.is_alphanumeric() { c } else { '-' })
		.collect();
	let s = s.split('-').filter(|p| !p.is_empty()).collect::<Vec<_>>().join("-");
	s
}

