// CaesarShift shifts each letter by n places, wrapping around the alphabet.
func CaesarShift(text string, n int) string {
	out := []byte(text)
	for i, ch := range out {
		switch {
		case ch >= 'a' && ch <= 'z':
			out[i] = byte('a' + (ch-'a'+byte(n)%26+26)%26)
		case ch >= 'A' && ch <= 'Z':
			out[i] = byte('A' + (ch-'A'+byte(n)%26+26)%26)
		}
	}
	return string(out)
}

// Example:
// fmt.Println(CaesarShift("Hello, World!", 3)) // Khoor, Zruog!

