// Shuffle returns a random permutation of items (Fisher–Yates).
func Shuffle[T any](items []T, rnd *rand.Rand) []T {
	out := append([]T(nil), items...) // copy
	for i := len(out) - 1; i > 0; i-- {
		j := rnd.Intn(i + 1)
		out[i], out[j] = out[j], out[i]
	}
	return out
}

