fn shuffle<T: Clone>(mut items: Vec<T>, rng: &mut impl rand::Rng) -> Vec<T> {
	for i in (1..items.len()).rev() {
		let j = rng.gen_range(0..=i);
		items.swap(i, j);
	}
	items
